INSERT INTO blog_seo (slug, title, description, image_url, page_type) VALUES ('embedded-mobility-services', 'Embedded Mobility Services | NetworkCore', 'Embedded mobility services are how EV charging moves from infrastructure play to platform revenue. Embed charging natively, earn per session, and own the driver relationship.', '/images/blog/embedded-mobility-services.jpg', 'blog') ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, image_url = EXCLUDED.image_url;